import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"State","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/state.md","filePath":"03-developer/models/state.md"}`),a={name:`03-developer/models/state.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to “State”">​</a></h1><p>The <code>State</code> model is used to store information about states or provinces. Each record includes the state&#39;s name, geographic coordinates, and the name of its country.</p><h2 id="data-structure" tabindex="-1">Data structure <a class="header-anchor" href="#data-structure" aria-label="Permalink to “Data structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique state or province ID</td></tr><tr><td><code>name</code></td><td>TEXT</td><td>No</td><td>State or province name; translatable</td></tr><tr><td><code>lat</code></td><td>DOUBLE</td><td>No</td><td>Latitude of the state or province</td></tr><tr><td><code>lng</code></td><td>DOUBLE</td><td>No</td><td>Longitude of the state or province</td></tr><tr><td><code>country</code></td><td>TEXT</td><td>No</td><td>Name of the country associated with the state or province; translatable</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time of the last record update</td></tr><tr><td><code>deleted_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record soft deletion time</td></tr></tbody></table><h2 id="relationships" tabindex="-1">Relationships <a class="header-anchor" href="#relationships" aria-label="Permalink to “Relationships”">​</a></h2><ul><li><code>cities()</code>: A <code>hasMany</code> relationship with the <code>City</code> model; returns the cities associated with this state or province.</li></ul><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="translatable" tabindex="-1"><code>$translatable</code> <a class="header-anchor" href="#translatable" aria-label="Permalink to “$translatable”">​</a></h3><p>The <code>name</code> and <code>country</code> fields are defined as translatable.</p><p>This feature allows values to be stored and displayed in the selected language. For example, a state&#39;s name can be &quot;تهران&quot; in Persian and <code>Tehran</code> in English.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="cities" tabindex="-1"><code>cities()</code> <a class="header-anchor" href="#cities" aria-label="Permalink to “cities()”">​</a></h3><p>Retrieves the cities associated with the state or province through the <code>City</code> model using a <code>hasMany</code> relationship.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>The <code>lat</code> and <code>lng</code> fields store the geographic coordinates of the state or province and can be used to improve the user experience when selecting a location on a map (Map Picker).</li><li>The <code>country</code> field stores the name of the country associated with the state or province and is a text field (<code>TEXT</code>), not a numeric ID.</li><li>The <code>deleted_at</code> field exists in the table structure and is used to record the time of soft deletion; whether Soft Deletes is enabled in the model depends on its configuration.</li><li>No foreign keys or other indexes are defined in the table structure besides the primary key <code>id</code>.</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};